from collections import deque
fg={(r,c) for r,cs in enumerate(rows) for c in cs}
vis=set(); q=deque()
for r in range(H):
 for c in range(W):
  if (r in (0,H-1) or c in (0,W-1)) and (r,c) not in fg: vis.add((r,c)); q.append((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  p=(r+dr,c+dc)
  if 0<=p[0]<H and 0<=p[1]<W and p not in fg and p not in vis: vis.add(p);q.append(p)
holes={(r,c) for r in range(H) for c in range(W) if (r,c) not in fg and (r,c) not in vis}
print(sorted(holes)); print(len(holes))
for r in range(H): print(''.join('5' if (r,c) in fg else '4' if (r,c) in holes else '9' for c in range(W)))
